// Extract product data and check if jewelry category
const body = $json.body || $json;

const productName = body.name || body.handle || 'Unknown Product';
const sku = body.sku || body.supply_price || '';
const categoryName = (body.product_type?.name || body.type || body.brand_name || '').toLowerCase();

// Check if this is a jewelry product
const jewelryKeywords = ['jewelry', 'jewellery', 'ring', 'necklace', 'earring', 'piercing jewelry', 'body jewelry'];
const isJewelry = jewelryKeywords.some(kw => categoryName.includes(kw));

if (!isJewelry) {
  return []; // Skip non-jewelry products
}

// Get inventory count and reorder point
const inventory = body.inventory || [];
const primaryInventory = Array.isArray(inventory) && inventory.length > 0 ? inventory[0] : body;
const currentCount = parseInt(primaryInventory.count || primaryInventory.current_amount || 0, 10);
const reorderPoint = parseInt(primaryInventory.reorder_point || primaryInventory.reorder_level || 0, 10);

if (reorderPoint <= 0) {
  return []; // No reorder point set — skip
}

const isLow = currentCount <= reorderPoint;
const isSoldOut = currentCount === 0;

if (!isLow) {
  return []; // Stock is fine — skip
}

return [{
  json: {
    productName,
    sku,
    categoryName,
    currentCount,
    reorderPoint,
    isLow,
    isSoldOut,
    productId: body.id || ''
  }
}];

// Deduplication: check if alert was sent for this SKU in last 24 hours
const product = $json;
const sku = product.sku || product.productId;

// Use n8n static data for dedup tracking
const staticData = $getWorkflowStaticData('global');
const alertLog = staticData.alertLog || {};
const now = Date.now();
const twentyFourHours = 24 * 60 * 60 * 1000;

// Clean up old entries
for (const [key, timestamp] of Object.entries(alertLog)) {
  if (now - timestamp > twentyFourHours) {
    delete alertLog[key];
  }
}

// Check dedup
if (alertLog[sku] && (now - alertLog[sku]) < twentyFourHours) {
  // Already alerted within 24 hours — skip
  return [];
}

// Record this alert
alertLog[sku] = now;
staticData.alertLog = alertLog;

// Check watched SKUs for immediate SOLD notification
const watchedSkus = staticData.watchedSkus || [];
const isWatched = watchedSkus.includes(sku);

return [{
  json: {
    ...product,
    isWatched,
    alertType: product.isSoldOut && isWatched ? 'SOLD' : 'LOW_STOCK'
  }
}];

